def seed_learning_articles(conn: sqlite3.Connection) -> int:
    """重复执行只更新同一 slug，不产生重复条目。"""
    now = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    for index, item in enumerate(ARTICLES):
        content = (
            f"内容导语\n{item['summary']}本专题以公开党史资料、政府公开信息和正式纪念场馆说明为依据，"
            "帮助读者从时间、地点、人物、实践和精神五个方面建立基本认识。\n\n"
            f"历史背景\n{item['event_time']}，相关实践主要发生在{item['location']}。理解该专题不能脱离当时的社会条件、"
            "主要矛盾和人民需要，也不能用今天的概念简单替代历史过程。资料库将事实陈述、精神阐释和青年感悟分层表达，"
            "使读者能够辨认哪些内容来自公开史料，哪些属于面向当代学习的整理。\n\n"
            f"形成与发展\n{item['process']}这一过程不是孤立节点，而是与党的理论探索、群众工作、组织建设和国家发展相互联系。"
            "阅读时可结合页面的时间轴、相关人物和推荐专题交叉核对，避免只记住一个结论。\n\n"
            f"代表人物与实践主体\n本专题涉及的主要实践主体包括：{item['related_people']}。人物资料应结合其所处时代、承担任务和集体实践理解，"
            "不以传奇化叙述替代可核验事实，也不把集体奋斗简化为单一个人故事。\n\n"
            f"核心内涵\n{item['spirit']}。这些概括来自长期实践经验的凝练，其价值不在于机械背诵，而在于理解理想信念、人民立场、"
            "实事求是、艰苦奋斗、团结协作和责任担当如何体现在具体行动中。\n\n"
            "历史意义与当代价值\n该专题帮助我们理解中国共产党团结带领人民解决现实问题的历史经验。今天学习相关内容，"
            "既要尊重历史事实，也要关注公共服务、科学精神、文化保护和社会协作，让精神价值进入可观察、可评价的日常实践。\n\n"
            f"青年启示\n{item['youth']}青年可以从一次规范引用、一次耐心访谈、一次无障碍改进和一次完整测试开始，"
            "把学习成果转化为有边界、有质量、能持续的行动。\n\n"
            "延伸阅读与资料边界\n本专题按照时间、空间、人物、过程、意义和精神六个维度组织信息。"
            "页面媒体按文章与章节建立对应关系，并明确区分旧址照片、纪念馆实景和项目自制信息图；不把当代照片标为历史现场。涉及精确日期、人物职务和历史评价时，"
            "应继续以页面列出的权威公开来源、党史文献和纪念场馆正式说明为准。"
        )
        values = (
            item["title"], item["subtitle"], item["summary"], content, item["category"], item["sub_category"],
            item["scope"], item["event_time"], item["location"], item["related_people"], item["spirit"], item["youth"],
            f"{item['category']},{item['sub_category']},红色文化,青年学习",
            f"/assets/images/party-history/info-{item['slug']}.jpg",
            f"《{item['title']}》项目自制信息图，概括本专题时间、地点与关键词；不是历史现场照片。",
            "中共中央党史和文献研究相关公开资料、政府公开资料", item["source_url"],
            "权威公开资料整理", 1 if index < 12 else 0, now, now, item["slug"],
        )
        conn.execute(
            """
            INSERT INTO learning_articles(
                title,subtitle,summary,content,category,sub_category,scope,event_time,location,related_people,
                spirit,youth_insight,tags,image,image_note,source_name,source_url,verification_status,featured,created_at,updated_at,slug
            ) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
            ON CONFLICT(slug) DO UPDATE SET
                title=excluded.title, subtitle=excluded.subtitle, summary=excluded.summary, content=excluded.content,
                category=excluded.category, sub_category=excluded.sub_category, scope=excluded.scope,
                event_time=excluded.event_time, location=excluded.location, related_people=excluded.related_people,
                spirit=excluded.spirit, youth_insight=excluded.youth_insight, tags=excluded.tags, image=excluded.image,
                image_note=excluded.image_note, source_name=excluded.source_name, source_url=excluded.source_url,
                verification_status=excluded.verification_status, featured=excluded.featured, updated_at=excluded.updated_at
            """,
            values,
        )
    return len(ARTICLES)


if __name__ == "__main__":
    from pathlib import Path

    database = Path(__file__).resolve().parents[1] / "database" / "maogongshan.db"
    with sqlite3.connect(database) as connection:
        seed_learning_articles(connection)
    print(f"党史学习资料已同步：{len(ARTICLES)} 条")
